bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 30
docker exec -i "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
const pool=new pg.Pool({
 host:process.env.VIDEOBOT_DB_HOST,
 user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,
 password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:4500
});
let code=100;
try{
 const {rows:[r]}=await pool.query(`
 SELECT
 (SELECT count(*) FROM videobot_post_receipts) AS receipt_count,
 (SELECT count(*) FROM videobot_post_receipts WHERE status='sent') AS posted_count,
 (SELECT count(*) FROM videobot_post_receipts WHERE sale_mode='invoice' AND status='sent') AS invoice_count,
 (SELECT count(*) FROM videobot_video_invoice_orders WHERE telegram_payment_charge_id IS NOT NULL) AS invoice_paid,
 (SELECT count(*) FROM videobot_stars_ledger WHERE kind='paid') AS ledger_paid,
 (SELECT count(*) FROM videobot_post_receipts WHERE topic_id=4672) AS topic4672_count,
 (SELECT count(*) FROM videobot_post_receipts WHERE topic_id=4640) AS topic4640_count
 `);
 if(Number(r.receipt_count)>0)code+=1;
 if(Number(r.posted_count)>0)code+=2;
 if(Number(r.invoice_count)>0)code+=4;
 if(Number(r.invoice_paid)>0)code+=8;
 if(Number(r.ledger_paid)>0)code+=16;
 if(Number(r.receipt_count)>1)code+=32;
 if(Number(r.topic4672_count)>0)code+=64;
 if(Number(r.topic4640_count)>0)code+=128;
}finally{await pool.end()}
process.exit(code);
NODE
